-- Migration 039: 70 more real, local Georgia organizations, all distinct from
-- migrations 008, 036, 037, and 038. Broad category coverage across ~25 cities:
-- Atlanta metro (Marietta, Kennesaw, Decatur, Dunwoody, Johns Creek, Lawrenceville,
-- Norcross, Chamblee, Fayetteville), plus Savannah, Augusta, Macon, Columbus,
-- Athens, Gainesville, Albany, Valdosta, Cumming, Brunswick, Rome, Cartersville,
-- Watkinsville, Canton, and statewide. Each org was researched individually and
-- its website/volunteer page verified. Pure inserts with fixed ids - safe to
-- re-run, existing rows untouched.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
