  ('d3000000-0000-4000-8000-000000000059', null, 'NPower', 'A nonprofit that launches underserved young adults and veterans into tech careers with free training, supported by volunteer mentors and coaches.', 'https://www.npower.org', 'https://www.google.com/s2/favicons?domain=www.npower.org&sz=128', 'tech', array['recurring', 'leadership role'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000060', null, 'GeorgiaFIRST Robotics', 'The Georgia arm of FIRST, inspiring young people in science and technology through mentor-based robotics programs and competitions.', 'https://gafirst.org', 'https://www.google.com/s2/favicons?domain=gafirst.org&sz=128', 'tech', array['recurring', 'leadership role', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- SPORTS
  ('d3000000-0000-4000-8000-000000000061', null, 'Atlanta Track Club', 'A running nonprofit (home of the Peachtree Road Race) that relies on more than 8,000 volunteers a year and runs youth running programs.', 'https://www.atlantatrackclub.org', 'https://www.google.com/s2/favicons?domain=www.atlantatrackclub.org&sz=128', 'sports', array['good for crews', 'family friendly', 'outdoors'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000062', null, 'YMCA of Coastal Georgia', 'A Savannah-area YMCA serving the coast for over 160 years through youth development, healthy living, and social responsibility programs.', 'https://www.ymcaofcoastalga.org', 'https://www.google.com/s2/favicons?domain=www.ymcaofcoastalga.org&sz=128', 'sports', array['recurring', 'leadership role', 'family friendly'], false, false, 15, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000063', null, 'Miracle League of Valdosta', 'A south Georgia baseball league for children with special needs, where volunteer buddies help players bat, run bases, and field.', 'https://www.valdostamiracles.org', 'https://www.google.com/s2/favicons?domain=www.valdostamiracles.org&sz=128', 'sports', array['recurring', 'family friendly', 'outdoors'], false, false, 12, 'United States', 'GA', 'Valdosta', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000064', null, 'Miracle League of Cumming Forsyth County', 'A north Georgia baseball league for children and adults with disabilities, where volunteer buddies support players on a specially designed field.', 'https://www.miracleleaguecfc.com', 'https://www.google.com/s2/favicons?domain=www.miracleleaguecfc.com&sz=128', 'sports', array['recurring', 'family friendly', 'outdoors'], false, false, 12, 'United States', 'GA', 'Cumming', true, true, 'both', false),
  -- FAITH
  ('d3000000-0000-4000-8000-000000000065', null, 'St. Vincent de Paul Georgia', 'A Catholic nonprofit founded in Atlanta in 1903 with 73 local hubs, food pantries, and thrift stores staffed by 3,000-plus trained volunteers.', 'https://svdpgeorgia.org', 'https://www.google.com/s2/favicons?domain=svdpgeorgia.org&sz=128', 'faith', array['recurring', 'good for crews', 'family friendly'], false, false, 16, 'United States', 'GA', 'Chamblee', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000066', null, 'Buckhead Christian Ministry', 'A community of volunteers bringing financial stability and hope to Atlanta neighbors in crisis, with roles as brief as three hours a month.', 'https://buckheadchristianministry.org', 'https://www.google.com/s2/favicons?domain=buckheadchristianministry.org&sz=128', 'faith', array['recurring', 'good for crews'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000067', null, 'Clifton Sanctuary Ministries', 'An Atlanta faith-based shelter transforming the lives of homeless men, with 300-plus volunteers providing meals, mentoring, and life-skills coaching.', 'https://www.cliftonsanctuary.com', 'https://www.google.com/s2/favicons?domain=www.cliftonsanctuary.com&sz=128', 'faith', array['recurring', 'good for crews'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- MUSIC
  ('d3000000-0000-4000-8000-000000000068', null, 'Nuçi''s Space', 'An Athens nonprofit supporting the mental health of musicians and preventing suicide, with volunteers staffing the front desk and practice spaces.', 'https://www.nuci.org', 'https://www.google.com/s2/favicons?domain=www.nuci.org&sz=128', 'music', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Athens', true, true, 'both', false),
  ('d3000000-0000-4000-8000-000000000069', null, 'AthFest Educates', 'An Athens nonprofit that funds music and arts education for K-12 youth in Athens-Clarke County through its annual festival and half marathon.', 'https://athfesteducates.org', 'https://www.google.com/s2/favicons?domain=athfesteducates.org&sz=128', 'music', array['recurring', 'creative work', 'good for crews'], false, false, 16, 'United States', 'GA', 'Athens', true, true, 'both', false),
  -- SENIORS
  ('d3000000-0000-4000-8000-000000000070', null, 'Marcus Jewish Community Center of Atlanta', 'A Dunwoody community center founded in 1910 serving people of all ages and backgrounds, including frail older adults and people with disabilities.', 'https://www.atlantajcc.org', 'https://www.google.com/s2/favicons?domain=www.atlantajcc.org&sz=128', 'seniors', array['recurring', 'family friendly'], false, false, 14, 'United States', 'GA', 'Dunwoody', true, true, 'both', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('d4000000-0000-4000-8000-000000000001', 'd3000000-0000-4000-8000-000000000001', 'Care for Cats at a No-Kill Shelter', 'animals', 'Volunteers help socialize and care for the cats at Good Mews, metro Atlanta''s first cage-free, no-kill cat shelter in Marietta. Duties include cleaning, feeding, and giving the cats affection and enrichment. It is a great fit if you love cats and want a steady, recurring role.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.goodmews.org/', 'https://www.goodmews.org/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d4000000-0000-4000-8000-000000000002', 'd3000000-0000-4000-8000-000000000002', 'Support the Dog Training Program', 'animals', 'Volunteers help support Canine CellMates, which pairs shelter dogs with incarcerated handlers for training and a second chance. Volunteers must be at least 18 given the jail-based program. It is a unique way to help both dogs and people turn their lives around.', array['recurring', 'leadership role'], 18, false, false, true, '2-3 hrs', 'https://www.caninecellmates.org/volunteer.html', 'https://www.caninecellmates.org/volunteer.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000003', 'd3000000-0000-4000-8000-000000000003', 'Foster a Rescue Dog', 'animals', 'Volunteers foster dogs, help at adoption events, and support this 100 percent volunteer-run rescue that saves dogs from high-kill shelters. Fostering is the biggest need and a great option if your household can host a dog. Start through the site to learn about open roles.', array['recurring', 'family friendly'], 18, false, false, true, 'Varies', 'https://www.releashatlanta.com/', 'https://www.releashatlanta.com/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000004', 'd3000000-0000-4000-8000-000000000004', 'Care for Rescue Rabbits', 'animals', 'Volunteers help feed, clean, and socialize rabbits at Georgia''s largest bunny rescue in Kennesaw, with flexible 1-to-3-hour shifts and no long commitment required. Teens can help with a guardian. It is a fun, low-pressure way to work with animals you rarely get to meet.', array['recurring', 'family friendly'], 12, false, false, true, '1-3 hrs', 'https://www.houserabbitga.com/', 'https://www.houserabbitga.com/', '2026-01-01T00:00:00Z', 'Kennesaw', 'GA'),
  ('d4000000-0000-4000-8000-000000000005', 'd3000000-0000-4000-8000-000000000005', 'Help Save Savannah''s Pets', 'animals', 'Volunteers foster pets, help at adoption events, and support the day-to-day work of this volunteer-based Savannah rescue. There are roles for many schedules, and fostering is especially valued. It is a great way to help coastal Georgia''s animals find homes.', array['recurring', 'family friendly'], 16, false, false, true, 'Varies', 'https://www.oneloveanimalrescue.com/', 'https://www.oneloveanimalrescue.com/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000006', 'd3000000-0000-4000-8000-000000000006', 'Walk Dogs and Foster Pets', 'animals', 'Volunteers walk dogs, foster animals, and help at this all-volunteer humane society north of Atlanta. Check their site and social media for dog-walking days and to apply. It is a flexible, hands-on way to help shelter animals in Cherokee County.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.humanecherokeecounty.org/volunteer', 'https://www.humanecherokeecounty.org/volunteer', '2026-01-01T00:00:00Z', 'Canton', 'GA'),
  ('d4000000-0000-4000-8000-000000000007', 'd3000000-0000-4000-8000-000000000007', 'Be a Docent at MODA', 'art', 'Volunteers serve as docents and event helpers at the Museum of Design Atlanta, teaching visitors how design shapes the world. MODA asks for a one-year commitment and provides training and perks. It is a great fit if you love design, art, and working with the public.', array['recurring', 'creative work', 'leadership role'], 16, false, false, true, '3-4 hrs', 'https://www.museumofdesign.org/opportunities', 'https://www.museumofdesign.org/opportunities', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000008', 'd3000000-0000-4000-8000-000000000008', 'Lead Tours or Tend Gardens', 'art', 'Volunteers lead tours through historic houses and exhibitions, tend the gardens, or help at special events across the Atlanta History Center campus. There are public-facing and behind-the-scenes roles to fit your interests. Apply online, then attend an orientation to get started.', array['recurring', 'leadership role', 'outdoors'], 16, false, false, true, '3-4 hrs', 'https://www.atlantahistorycenter.com/support/volunteer/', 'https://www.atlantahistorycenter.com/support/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000009', 'd3000000-0000-4000-8000-000000000009', 'Help at Concerts and the Gardens', 'art', 'Volunteers staff festivals, concerts, and the holiday Winter House, or help in the gardens at Callanwolde Fine Arts Center, a small-staffed historic arts center. Some gardening experience is helpful but not required. It is a lovely place to give a few hours.', array['recurring', 'creative work'], 16, false, false, true, '2-4 hrs', 'https://callanwolde.org/volunteer/', 'https://callanwolde.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000010', 'd3000000-0000-4000-8000-000000000010', 'Volunteer at Aurora Theatre', 'art', 'Volunteers usher, help at productions, and support education programs at Aurora Theatre in Lawrenceville. If you love live theater, it is a way to be part of the action behind the scenes. Roles range from single shows to a season-long commitment.', array['recurring', 'creative work'], 16, false, false, true, '2-4 hrs', 'https://auroratheatre.com/support/volunteer/', 'https://auroratheatre.com/support/volunteer/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('d4000000-0000-4000-8000-000000000011', 'd3000000-0000-4000-8000-000000000011', 'Welcome Guests at a Maritime Museum', 'art', 'Volunteers greet visitors, help at events, and support exhibitions at the Ships of the Sea Maritime Museum, set in a historic Savannah mansion and gardens. It is a great fit if you love history and the sea. Reach out through the site to get involved.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://www.shipsofthesea.org/', 'https://www.shipsofthesea.org/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000012', 'd3000000-0000-4000-8000-000000000012', 'Become a Museum Docent in Athens', 'art', 'Volunteers train to lead tours at the Georgia Museum of Art on the UGA campus, giving about 12 tours a year over a two-year commitment. No art background is needed, since training and support are provided. It is a great fit if you enjoy public speaking and art.', array['recurring', 'leadership role'], 18, false, false, true, '2-3 hrs / month', 'https://georgiamuseum.org/join-and-give/volunteer/', 'https://georgiamuseum.org/join-and-give/volunteer/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d4000000-0000-4000-8000-000000000013', 'd3000000-0000-4000-8000-000000000013', 'Guide Tours of Western Art', 'art', 'Volunteers train as docents to lead daily and private tours for multi-generational audiences at the Booth Western Art Museum in Cartersville. There is an onboarding period and a fall training course. It is a strong pick if you love art, history, and meeting people.', array['recurring', 'leadership role'], 16, false, false, true, '4 hrs / month', 'https://boothmuseum.org/volunteer/', 'https://boothmuseum.org/volunteer/', '2026-01-01T00:00:00Z', 'Cartersville', 'GA'),
  ('d4000000-0000-4000-8000-000000000014', 'd3000000-0000-4000-8000-000000000014', 'Support Nature Education in Gainesville', 'environment', 'Volunteers maintain trails, support science and camp programs, help at events, and care for live animals at the Elachee Nature Science Center and its preserve. Roles suit a range of ages and interests. It is a beautiful outdoor place to give your time in north Georgia.', array['outdoors', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://elachee.org/volunteer/', 'https://elachee.org/volunteer/', '2026-01-01T00:00:00Z', 'Gainesville', 'GA'),
  ('d4000000-0000-4000-8000-000000000015', 'd3000000-0000-4000-8000-000000000015', 'Join a Second-Saturday Workday', 'environment', 'On the second Saturday of each month, volunteers clear trails, remove invasive plants, spread mulch, and plant at the Dunwoody Nature Center; there are also events like the Butterfly Festival. It is easy, hands-on outdoor work for individuals and groups. No experience needed.', array['outdoors', 'physical work', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://dunwoodynature.org/volunteer/', 'https://dunwoodynature.org/volunteer/', '2026-01-01T00:00:00Z', 'Dunwoody', 'GA'),
  ('d4000000-0000-4000-8000-000000000016', 'd3000000-0000-4000-8000-000000000016', 'Restore Trails at Autrey Mill', 'environment', 'Volunteers help with trail maintenance, invasive-species removal, and educational outreach at the Autrey Mill Nature Preserve in Johns Creek, including quarterly group workdays. It is great for school, Scout, and corporate groups. Expect satisfying outdoor work.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://autreymill.org/', 'https://autreymill.org/', '2026-01-01T00:00:00Z', 'Johns Creek', 'GA'),
  ('d4000000-0000-4000-8000-000000000017', 'd3000000-0000-4000-8000-000000000017', 'Lead Bird Walks and Restore Habitat', 'environment', 'Volunteers lead field trips, act as naturalists, restore habitat, and help at programs with Georgia Audubon (Birds Georgia). It is a strong pick if you love birds and the outdoors. Roles range from one-time restoration days to ongoing leadership positions.', array['outdoors', 'recurring', 'leadership role'], 14, false, false, true, '2-3 hrs', 'https://www.birdsgeorgia.org/volunteer.html', 'https://www.birdsgeorgia.org/volunteer.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000018', 'd3000000-0000-4000-8000-000000000018', 'Monitor and Clean the Coosa', 'environment', 'Volunteers help with water monitoring, education, and river cleanups with the Coosa River Basin Initiative in Rome, protecting one of the most biodiverse river systems in North America. Sign up for notifications when projects come up. It is meaningful, hands-on conservation.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://coosa.org/volunteer/', 'https://coosa.org/volunteer/', '2026-01-01T00:00:00Z', 'Rome', 'GA'),
  ('d4000000-0000-4000-8000-000000000019', 'd3000000-0000-4000-8000-000000000019', 'Get Boots in the Water on the Altamaha', 'environment', 'Volunteers help monitor water quality, report pollution, and clean up along Georgia''s largest river with the Altamaha Riverkeeper. It is hands-on outdoor work that protects a river and coast many people depend on. Reach out through the site to join a project.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-4 hrs', 'https://altamahariverkeeper.org/', 'https://altamahariverkeeper.org/', '2026-01-01T00:00:00Z', 'Brunswick', 'GA'),
  ('d4000000-0000-4000-8000-000000000020', 'd3000000-0000-4000-8000-000000000020', 'Protect the Flint River', 'environment', 'Volunteers help restore and protect the habitat, water quality, and flow of the Flint River and its tributaries with Flint Riverkeeper, based in Albany. Roles include cleanups and monitoring. It is a great way to care for a beloved south Georgia river.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-4 hrs', 'https://www.flintriverkeeper.org/', 'https://www.flintriverkeeper.org/', '2026-01-01T00:00:00Z', 'Albany', 'GA'),
  ('d4000000-0000-4000-8000-000000000021', 'd3000000-0000-4000-8000-000000000021', 'Plant Trees in Columbus', 'environment', 'Volunteers help plant and care for trees at community plantings with Trees Columbus, plus office and social-media roles. It is satisfying outdoor work that greens the Columbus area for the long haul. Join their email list for upcoming plantings.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://www.treescolumbus.org/', 'https://www.treescolumbus.org/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('d4000000-0000-4000-8000-000000000022', 'd3000000-0000-4000-8000-000000000022', 'Serve at the Hosea Helps Care Center', 'community', 'Volunteers sort donations, pack food, and support families at the Hosea Helps Care Center in Atlanta, open Tuesday through Saturday. You can serve for as little as two hours, which makes it easy to earn service hours. It is one of the most flexible ways to help in the city.', array['good for crews', 'family friendly', 'counts for school hours'], 12, false, false, true, '2-4 hrs', 'https://4hosea.org/volunteers/', 'https://4hosea.org/volunteers/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000023', 'd3000000-0000-4000-8000-000000000023', 'Tutor or Mentor at Rainbow Village', 'community', 'Volunteers tutor kids after school, mentor adults, prep and serve meals, or help with grounds at Rainbow Village in Duluth, which serves families experiencing homelessness. There are roles for many skills and schedules. It is a rewarding way to help families reach stability.', array['recurring', 'good for crews', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://rainbowvillage.org/get-involved/', 'https://rainbowvillage.org/get-involved/', '2026-01-01T00:00:00Z', 'Duluth', 'GA'),
  ('d4000000-0000-4000-8000-000000000024', 'd3000000-0000-4000-8000-000000000024', 'Host Families Overcoming a Housing Crisis', 'community', 'Volunteers prepare meals, host families, and help with projects supporting families in a housing crisis through Family Promise of North Fulton/DeKalb. Roles are available during the day, evening, and weekends, with orientation and training provided. It is a direct way to help families back into stable housing.', array['recurring', 'family friendly', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.familypromisenfd.org/', 'https://www.familypromisenfd.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000025', 'd3000000-0000-4000-8000-000000000025', 'Join the Welcome or Dinner Team', 'community', 'Volunteers serve on the Weekend Welcome Team or as Dinner and Evening Hosts, supporting homeless children and families with Family Promise of Gwinnett in Lawrenceville. There are roles for individuals and groups. It is a warm, hands-on way to help families regain independence.', array['recurring', 'family friendly', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://familypromisegwinnett.org/get-involved/volunteer/', 'https://familypromisegwinnett.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('d4000000-0000-4000-8000-000000000026', 'd3000000-0000-4000-8000-000000000026', 'Cook and Host with Family Promise Cobb', 'community', 'Volunteers provide meals, lodging support, and hospitality to families experiencing homelessness through Family Promise of Cobb County''s network of host congregations. Group projects include painting, yardwork, and crafts with children. It is a meaningful way to help families stay together.', array['recurring', 'family friendly', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.fpcobb.org/', 'https://www.fpcobb.org/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d4000000-0000-4000-8000-000000000027', 'd3000000-0000-4000-8000-000000000027', 'Help at the Pantry and Thrift Store', 'community', 'Volunteers sort and distribute food and help in the thrift store at Neighborhood Cooperative Ministries, which serves families across Gwinnett County. There are roles for individuals and groups. It is a welcoming place to give a few hours close to home.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.ourncm.org/', 'https://www.ourncm.org/', '2026-01-01T00:00:00Z', 'Norcross', 'GA'),
  ('d4000000-0000-4000-8000-000000000028', 'd3000000-0000-4000-8000-000000000028', 'Support Survivors at Wellspring Living', 'community', 'Volunteers help in the retail stores, on serve days, and in programs supporting survivors of sex trafficking and exploitation through Wellspring Living. Given the sensitive work, volunteers are 18 and up. It is a powerful way to help survivors find safety and hope.', array['recurring', 'good for crews'], 18, false, false, true, '2-3 hrs', 'https://wellspringliving.org/get-involved/volunteer/', 'https://wellspringliving.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000029', 'd3000000-0000-4000-8000-000000000029', 'Strengthen Latino Families', 'community', 'Volunteers share their time and skills to support Ser Familia''s programs for Latino youth, couples, and families across Georgia. Bilingual volunteers are especially valued, but there is a role for everyone. It is a great fit if you want to support families and community.', array['recurring', 'counts for school hours', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://serfamilia.org/get-involved/volunteer/', 'https://serfamilia.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d4000000-0000-4000-8000-000000000030', 'd3000000-0000-4000-8000-000000000030', 'Cook Dinner for Grove Park Families', 'community', 'Volunteers provide dinner twice a month so parents and kids can share a family meal, plus other roles at PAWKids, a community hub in Atlanta''s Grove Park. It is a warm, family-friendly way to help. Reach out through the site to find a fit.', array['recurring', 'family friendly', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://www.pawkids.org/get-involved', 'https://www.pawkids.org/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000031', 'd3000000-0000-4000-8000-000000000031', 'Help Guests Access Services', 'community', 'Volunteers work one-on-one with guests at the Central Outreach and Advocacy Center in downtown Atlanta, helping with IDs, birth certificates, referrals, and other services that overcome and prevent homelessness. There are one-time, monthly, and weekly roles. It is direct, meaningful help.', array['recurring', 'leadership role'], 16, false, false, true, '3-4 hrs', 'https://centraloac.org/get-involved/volunteer/', 'https://centraloac.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000032', 'd3000000-0000-4000-8000-000000000032', 'Support Union Mission Programs', 'community', 'Volunteers help with meals, donations, and community programs at Union Mission in Savannah, which provides shelter, housing, and health services. There are roles for individuals and groups. It is a solid way to help neighbors experiencing homelessness on the coast.', array['good for crews', 'recurring'], 16, false, false, true, '2-3 hrs', 'https://www.unionmission.org/volunteer', 'https://www.unionmission.org/volunteer', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000033', 'd3000000-0000-4000-8000-000000000033', 'Support At-Risk Youth in Savannah', 'community', 'Volunteers help with programs, meals, and activities at Park Place Outreach, a Savannah emergency shelter for youth ages 11 to 17. Given the residential setting, volunteers are generally 18 and up. It is a meaningful role supporting kids and reunifying families.', array['recurring', 'good for crews'], 18, false, false, true, '2-3 hrs', 'https://parkplaceyes.org/get-involved/', 'https://parkplaceyes.org/get-involved/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000034', 'd3000000-0000-4000-8000-000000000034', 'Support Job Training at Goodwill', 'community', 'Volunteers help at Goodwill Southeast Georgia, whose donated-goods sales fund job training and career services across the coast. Roles range from sorting donations to supporting career programs. It is a good pick if you want to help people find work.', array['recurring', 'good for crews'], 16, false, false, true, '2-3 hrs', 'https://goodwillsega.org/volunteer/', 'https://goodwillsega.org/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000035', 'd3000000-0000-4000-8000-000000000035', 'Mentor Kids at the Augusta Club', 'community', 'Volunteers help with after-school programs, sports, and mentoring at the Boys & Girls Clubs of Greater Augusta. Volunteers are 18 and up and commit to one consistent day a week for 8 to 12 weeks. It is a great steady role working with youth.', array['recurring', 'leadership role', 'family friendly'], 18, false, false, true, '2-3 hrs / week', 'https://bgcgreateraugusta.org/volunteer', 'https://bgcgreateraugusta.org/volunteer', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('d4000000-0000-4000-8000-000000000036', 'd3000000-0000-4000-8000-000000000036', 'Volunteer at a Camp for Kids with Cancer', 'medicine', 'Volunteers help run year-round programs for children with cancer and their families at Camp Sunshine, with medical and general roles. All volunteers complete an application, training, and a background check. It is a joyful, meaningful way to support kids through treatment.', array['recurring', 'leadership role', 'outdoors'], 16, false, false, true, 'Varies', 'https://www.mycampsunshine.com/volunteer/volunteer/', 'https://www.mycampsunshine.com/volunteer/volunteer/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('d4000000-0000-4000-8000-000000000037', 'd3000000-0000-4000-8000-000000000037', 'Support Campers with Disabilities', 'medicine', 'Volunteers help at camps and year-round programs for children and adults with disabilities at Extra Special People in Watkinsville. It is high-energy, joyful work centered on belonging and inclusion. Great for anyone who loves working with people of all abilities.', array['recurring', 'leadership role', 'family friendly'], 16, false, false, true, 'Varies', 'https://espyouandme.org/', 'https://espyouandme.org/', '2026-01-01T00:00:00Z', 'Watkinsville', 'GA'),
  ('d4000000-0000-4000-8000-000000000038', 'd3000000-0000-4000-8000-000000000038', 'Support People with Disabilities', 'medicine', 'Volunteers support participants and programs at the Bobby Dodd Institute, which helps people with disabilities gain skills and independence, including its Grow work-experience program for teens and young adults. Roles fit many skills and schedules. It is a great fit if you value inclusion.', array['recurring', 'good for crews'], 16, false, false, true, '2-3 hrs', 'https://bobbydodd.org/volunteer/', 'https://bobbydodd.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000039', 'd3000000-0000-4000-8000-000000000039', 'Serve Atlanta''s Uninsured', 'medicine', 'Volunteers support Mercy Care, which takes health care to people who are homeless and uninsured across Atlanta, in clinical and community roles. It is an excellent fit if you are considering a health career or want to support health equity. Training and placement are provided.', array['recurring'], 18, false, false, true, '2-3 hrs', 'https://mercyatlanta.org/volunteer/', 'https://mercyatlanta.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000040', 'd3000000-0000-4000-8000-000000000040', 'Support Community Health and Early Learning', 'medicine', 'Volunteers help with programs and events at Whitefoord, which provides community health care and early education in Atlanta. Email to share your area of interest and get matched. It is a good fit if you care about health and education equity.', array['recurring', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://www.whitefoord.org/contact', 'https://www.whitefoord.org/contact', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000041', 'd3000000-0000-4000-8000-000000000041', 'Volunteer at Memorial Health', 'medicine', 'Volunteers enhance patient care at Memorial Health in Savannah, including its children''s hospital, by supporting patients, families, and visitors across departments. You complete an application, background check, orientation, and health screening first. It is a strong fit if you are exploring a health career.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://memorial.health/about-us/volunteer/', 'https://memorial.health/about-us/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000042', 'd3000000-0000-4000-8000-000000000042', 'Volunteer at a Gainesville Hospital', 'medicine', 'Volunteers provide non-medical support to patients, families, and visitors at Northeast Georgia Health System in Gainesville, which welcomes high schoolers 16 and up alongside adults and college students. It is a great option if you are interested in health care. Contact Volunteer Services to begin.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.nghs.com/volunteer', 'https://www.nghs.com/volunteer', '2026-01-01T00:00:00Z', 'Gainesville', 'GA'),
  ('d4000000-0000-4000-8000-000000000043', 'd3000000-0000-4000-8000-000000000043', 'Be a Phoebe Volunteer', 'medicine', 'Volunteers serve in more than 60 areas at Phoebe Putney in Albany, from greeting visitors and bringing patients warm blankets to running the gift-shop register. Volunteers are valued members of the care team. It is a rewarding way to give back in southwest Georgia.', array['recurring'], 16, false, false, true, '3-4 hrs / week', 'https://phoebehealth.com/volunteer/', 'https://phoebehealth.com/volunteer/', '2026-01-01T00:00:00Z', 'Albany', 'GA'),
  ('d4000000-0000-4000-8000-000000000044', 'd3000000-0000-4000-8000-000000000044', 'Lead a Girl Scout Troop', 'education', 'Volunteers serve as troop leaders, event helpers, and award coaches with Girl Scouts of Greater Atlanta, building confidence and character in girls. No previous experience is required, and training is provided. It is a rewarding, recurring role mentoring the next generation.', array['recurring', 'leadership role', 'family friendly'], 18, false, false, true, '2-3 hrs / week', 'https://www.girlscoutsatl.org/en/get-involved/become-a-volunteer.html', 'https://www.girlscoutsatl.org/en/get-involved/become-a-volunteer.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000045', 'd3000000-0000-4000-8000-000000000045', 'Work with Young Learners', 'education', 'Volunteers work with children and families on center projects at Sheltering Arms, which provides early education to 3,600 kids a year across metro Atlanta. Groups of 10 to 30 can do half- or full-day projects. It is a great fit if you love little learners.', array['recurring', 'good for crews', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://shelteringarmsforkids.com/volunteer', 'https://shelteringarmsforkids.com/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000046', 'd3000000-0000-4000-8000-000000000046', 'Be a Reading Mentor in Athens', 'education', 'Volunteers read weekly one-on-one with second and third graders through the Books for Keeps literacy mentor program in Athens. It is a consistent, relationship-based role that helps kids build a love of reading. Training and books are provided.', array['recurring', 'counts for school hours', 'family friendly'], 16, false, false, true, '1 hr / week', 'https://www.booksforkeeps.org/', 'https://www.booksforkeeps.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d4000000-0000-4000-8000-000000000047', 'd3000000-0000-4000-8000-000000000047', 'Mentor Youth in Crisis', 'education', 'Volunteers mentor and support youth through Raising Expectations, which lifts academic and civic expectations for young people across Atlanta neighborhoods. It is a good fit if you want a steady mentoring role. Reach out through the site to get involved.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://raisingexpectations.org/get-involved/', 'https://raisingexpectations.org/get-involved/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000048', 'd3000000-0000-4000-8000-000000000048', 'Teach a Financial-Literacy Workshop', 'education', 'Volunteers lead fun, interactive financial-education sessions for youth through Operation HOPE, an Atlanta-founded nonprofit; the commitment is about one hour per session over a six-week program. Training is provided. It is a high-impact way to share practical money skills.', array['recurring', 'leadership role', 'counts for school hours'], 18, false, false, true, '1 hr / session', 'https://operationhope.org/join-us/volunteer/', 'https://operationhope.org/join-us/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000049', 'd3000000-0000-4000-8000-000000000049', 'Become a Big Brother or Big Sister', 'education', 'Volunteers 21 and up are matched one-to-one with a child ages 8 to 18 and spend time together doing everyday activities that build confidence and trust, with screening, training, and support from Big Brothers Big Sisters of Metro Atlanta. Because it is an ongoing relationship, expect a real commitment. It is one of the most rewarding mentoring roles around.', array['recurring', 'leadership role', 'counts for school hours'], 21, false, false, true, '2-4 hrs / month', 'https://bbbsatl.org/be-a-big/', 'https://bbbsatl.org/be-a-big/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000050', 'd3000000-0000-4000-8000-000000000050', 'Mentor Youth Through Chess', 'education', 'Volunteers mentor young people through chess and enrichment programs with Chess & Community in Athens, building critical thinking and leadership. You do not need to be a chess master, just willing to guide and encourage. It is a fun, meaningful way to support youth.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://www.chessandcommunity.org/', 'https://www.chessandcommunity.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d4000000-0000-4000-8000-000000000051', 'd3000000-0000-4000-8000-000000000051', 'Support Food-Service Workers in Crisis', 'food', 'Volunteers help Giving Kitchen, an Atlanta nonprofit that provides emergency assistance to food-service workers facing crisis, through events and community support. It is a great fit if you love the restaurant community and want to give back. Check the site for current roles.', array['good for crews', 'recurring'], 16, false, false, true, '2-3 hrs', 'https://givingkitchen.org/get-involved/volunteer/', 'https://givingkitchen.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000052', 'd3000000-0000-4000-8000-000000000052', 'Make Sandwiches for Neighbors', 'food', 'Volunteers assemble homemade sandwiches at home or in groups and deliver them to community partners with The Sandwich Project, which has donated more than two million sandwiches in metro Atlanta. It is one of the easiest, most family-friendly ways to fight hunger. Do it weekly or as a group event.', array['good for crews', 'family friendly', 'recurring'], 12, false, false, true, '1-2 hrs', 'https://www.thesandwichproject.org/give-your-time', 'https://www.thesandwichproject.org/give-your-time', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000053', 'd3000000-0000-4000-8000-000000000053', 'Pack Groceries for the Pantry', 'food', 'Volunteers prepare bags of pantry staples ahead of the Wednesday food distribution at Malachi''s Storehouse in the Decatur area, with shifts on Tuesdays and Wednesdays. It is a straightforward, welcoming way to fight local hunger. Good for individuals and groups.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2 hrs', 'https://malachis.org/', 'https://malachis.org/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('d4000000-0000-4000-8000-000000000054', 'd3000000-0000-4000-8000-000000000054', 'Work an Urban Farm on the BeltLine', 'gardening', 'Volunteers help plant, weed, and harvest at Aluma Farm, a 3.5-acre urban farm on the Atlanta BeltLine in Adair Park. It is a great way to get exercise and sunshine while learning to grow food. Weekly volunteer hours open in early summer.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.alumafarm.com/volunteer', 'https://www.alumafarm.com/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000055', 'd3000000-0000-4000-8000-000000000055', 'Garden and Teach at Oakhurst', 'gardening', 'Volunteers help tend the garden and support hands-on environmental education at the Oakhurst Community Garden in Decatur, part of the Wylde Center, with weekly volunteer days and special teams. No experience needed. It is a friendly, family-welcoming outdoor role.', array['outdoors', 'physical work', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://www.oakhurstgarden.org/', 'https://www.oakhurstgarden.org/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('d4000000-0000-4000-8000-000000000056', 'd3000000-0000-4000-8000-000000000056', 'Support Veterans and Kids at Camp', 'veterans', 'Volunteers help at Camp Southern Ground in Fayetteville, which serves children and runs free Warrior programs helping veterans transition to civilian life. There are camp, event, and grounds roles. It is a beautiful place to support veterans and kids alike.', array['recurring', 'outdoors', 'good for crews'], 18, false, false, true, 'Varies', 'https://campsouthernground.org/get-involved/', 'https://campsouthernground.org/get-involved/', '2026-01-01T00:00:00Z', 'Fayetteville', 'GA'),
  ('d4000000-0000-4000-8000-000000000057', 'd3000000-0000-4000-8000-000000000057', 'Help Veterans in Columbus', 'veterans', 'Volunteers support Warrior Outreach in Columbus through equine activities for veterans and families and a free "Veterans Helping Veterans" home-repair service. It is an all-volunteer organization, so your time makes a direct difference. Great for hands-on help close to home.', array['recurring', 'outdoors', 'good for crews'], 16, false, false, true, 'Varies', 'https://warrioroutreachranch.org/', 'https://warrioroutreachranch.org/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('d4000000-0000-4000-8000-000000000058', 'd3000000-0000-4000-8000-000000000058', 'Mentor a Young Adult in Tech', 'tech', 'Volunteers mentor young adults 18 to 24 as they build tech and professional skills and complete corporate internships with Year Up Greater Atlanta. It is a strong fit if you work in a professional field and want to help someone launch a career. Mentors support students through the program.', array['recurring', 'leadership role'], 21, false, false, true, '1-2 hrs / month', 'https://www.yearup.org/', 'https://www.yearup.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000059', 'd3000000-0000-4000-8000-000000000059', 'Coach Future Tech Professionals', 'tech', 'Volunteers run mock interviews, mentor students, and support professional development for young adults and veterans training for tech careers with NPower. It is a great fit if you work in tech or business and want to open doors for others. Register through their volunteer platform.', array['recurring', 'leadership role'], 18, false, false, true, '2-3 hrs', 'https://www.npower.org/become-a-volunteer/', 'https://www.npower.org/become-a-volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000060', 'd3000000-0000-4000-8000-000000000060', 'Mentor a Robotics Team', 'tech', 'Volunteers mentor student robotics teams and help run competitions with GeorgiaFIRST Robotics, inspiring young people in science and technology. You can share technical or organizational skills, and training is available. It is a fun, high-impact way to grow future innovators.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '2-3 hrs / week', 'https://gafirst.org/get-involved', 'https://gafirst.org/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000061', 'd3000000-0000-4000-8000-000000000061', 'Volunteer at a Race or Youth Run', 'sports', 'Volunteers staff water stops, packet pickup, and finish lines at Atlanta Track Club events (including the Peachtree Road Race) and support youth running programs. Volunteers are welcome from age 12. It is a fun, high-energy way to earn service hours with a crew.', array['good for crews', 'family friendly', 'outdoors'], 12, false, false, true, '3-4 hrs', 'https://www.atlantatrackclub.org/volunteers', 'https://www.atlantatrackclub.org/volunteers', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000062', 'd3000000-0000-4000-8000-000000000062', 'Support Youth Programs at the Coastal Y', 'sports', 'Volunteers coach youth sports, support swim and wellness programs, and mentor young people at the YMCA of Coastal Georgia in Savannah. Some programs welcome volunteers as young as 15. It is a great recurring role building character and community.', array['recurring', 'leadership role', 'family friendly'], 15, false, false, true, '2-3 hrs / week', 'https://www.ymcaofcoastalga.org/volunteer', 'https://www.ymcaofcoastalga.org/volunteer', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d4000000-0000-4000-8000-000000000063', 'd3000000-0000-4000-8000-000000000063', 'Be a Buddy at the Miracle League', 'sports', 'Volunteer buddies help children with special needs bat, run the bases, and field at Miracle League of Valdosta games on a specially designed field. Buddies are 12 and up (or in 6th grade). It is a joyful, feel-good way to spend a game day.', array['recurring', 'family friendly', 'outdoors'], 12, false, false, true, '2-3 hrs', 'https://www.valdostamiracles.org/volunteers.html', 'https://www.valdostamiracles.org/volunteers.html', '2026-01-01T00:00:00Z', 'Valdosta', 'GA'),
  ('d4000000-0000-4000-8000-000000000064', 'd3000000-0000-4000-8000-000000000064', 'Buddy Up at Miracle League Cumming', 'sports', 'Volunteer buddies support children and adults with disabilities as they play baseball on a specially designed field with the Miracle League of Cumming in Forsyth County. It is welcoming to youth and adult volunteers alike. Games are upbeat, social, and rewarding.', array['recurring', 'family friendly', 'outdoors'], 12, false, false, true, '2-3 hrs', 'https://www.miracleleaguecfc.com/', 'https://www.miracleleaguecfc.com/', '2026-01-01T00:00:00Z', 'Cumming', 'GA'),
  ('d4000000-0000-4000-8000-000000000065', 'd3000000-0000-4000-8000-000000000065', 'Serve as a Vincentian Volunteer', 'faith', 'Volunteers serve neighbors in need at St. Vincent de Paul Georgia''s food pantries, thrift stores, and local conferences, joining 3,000-plus trained volunteers statewide. There are roles for individuals and groups of many faiths. It is a welcoming way to give practical help.', array['recurring', 'good for crews', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://svdpgeorgia.org/get-involved/volunteer/', 'https://svdpgeorgia.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Chamblee', 'GA'),
  ('d4000000-0000-4000-8000-000000000066', 'd3000000-0000-4000-8000-000000000066', 'Support Neighbors in Crisis', 'faith', 'Volunteers help neighbors facing financial crisis at Buckhead Christian Ministry, with training provided and roles that can be as little as three hours a month. It is a flexible, welcoming way to help families reach stability. Reach out through the site to start.', array['recurring', 'good for crews'], 16, false, false, true, '3 hrs / month', 'https://buckheadchristianministry.org/volunteer/', 'https://buckheadchristianministry.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000067', 'd3000000-0000-4000-8000-000000000067', 'Cook or Mentor at a Men''s Shelter', 'faith', 'Volunteers provide meals, run the computer lab, and mentor residents at Clifton Sanctuary Ministries, an Atlanta shelter transforming the lives of homeless men. Given the residential setting, volunteers are 18 and up. It is a meaningful way to support men rebuilding their lives.', array['recurring', 'good for crews'], 18, false, false, true, '2-3 hrs', 'https://www.cliftonsanctuary.com/volunteer-opportunities', 'https://www.cliftonsanctuary.com/volunteer-opportunities', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d4000000-0000-4000-8000-000000000068', 'd3000000-0000-4000-8000-000000000068', 'Staff the Front Desk at Nuçi''s Space', 'music', 'Volunteers staff the front desk at Nuçi''s Space in Athens, greeting visitors, routing calls, and keeping the practice rooms tidy for a nonprofit that supports musicians'' mental health. Shifts run weekdays in two-hour blocks. It is a welcoming role in the heart of the Athens music scene.', array['recurring', 'creative work'], 16, false, false, true, '2 hrs / shift', 'https://www.nuci.org/volunteer', 'https://www.nuci.org/volunteer', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d4000000-0000-4000-8000-000000000069', 'd3000000-0000-4000-8000-000000000069', 'Help Fund Music and Arts Education', 'music', 'Volunteers help produce AthFest Educates events, including the AthFest Music and Arts Festival and the AthHalf half marathon, which fund music and arts education for K-12 youth in Athens-Clarke County. It is a fun, festival-style way to support arts education. Great for groups.', array['recurring', 'creative work', 'good for crews'], 16, false, false, true, '3-4 hrs', 'https://athfesteducates.org/', 'https://athfesteducates.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d4000000-0000-4000-8000-000000000070', 'd3000000-0000-4000-8000-000000000070', 'Bring Joy to Older Adults', 'seniors', 'Volunteers share their time, interests, and talents with residents and members at the Marcus Jewish Community Center of Atlanta in Dunwoody, which serves people of all ages including frail older adults. There are roles for many schedules. It is a warm way to brighten someone''s day.', array['recurring', 'family friendly'], 14, false, false, true, '1-2 hrs', 'https://www.atlantajcc.org/', 'https://www.atlantajcc.org/', '2026-01-01T00:00:00Z', 'Dunwoody', 'GA')
